-- The schema after every migration in portals/corp/backend/migrations, generated by tools/db-schema.
-- Read it; don't edit it: change the schema with a new migration, then run tools/db-schema.

CREATE TABLE public.heartbeat_samples (
    install_id uuid NOT NULL,
    received_at timestamp with time zone NOT NULL,
    decisions_per_second double precision,
    pdp_p99_ms double precision,
    error_rate double precision,
    kafka_lag bigint,
    clickhouse_disk_used_percent double precision,
    services_healthy integer NOT NULL,
    services_total integer NOT NULL
);

CREATE TABLE public.install_versions (
    install_id uuid NOT NULL,
    chart_version text NOT NULL,
    first_seen_at timestamp with time zone NOT NULL
);

CREATE TABLE public.installs (
    id uuid NOT NULL,
    client text NOT NULL,
    environment text NOT NULL,
    cloud text NOT NULL,
    region text NOT NULL,
    channel text NOT NULL,
    pinned_version text,
    token_sha256 bytea NOT NULL,
    created_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_heartbeat jsonb,
    last_seen_at timestamp with time zone,
    alerted_health text,
    held_health text,
    held_since timestamp with time zone,
    retired_at timestamp with time zone,
    retired_by text
);

ALTER TABLE ONLY public.heartbeat_samples
    ADD CONSTRAINT heartbeat_samples_pkey PRIMARY KEY (install_id, received_at);

ALTER TABLE ONLY public.install_versions
    ADD CONSTRAINT install_versions_pkey PRIMARY KEY (install_id, chart_version);

ALTER TABLE ONLY public.installs
    ADD CONSTRAINT installs_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.installs
    ADD CONSTRAINT installs_token_sha256_key UNIQUE (token_sha256);

CREATE UNIQUE INDEX installs_client_environment_active ON public.installs USING btree (client, environment) WHERE (retired_at IS NULL);

ALTER TABLE ONLY public.heartbeat_samples
    ADD CONSTRAINT heartbeat_samples_install_id_fkey FOREIGN KEY (install_id) REFERENCES public.installs(id);

ALTER TABLE ONLY public.install_versions
    ADD CONSTRAINT install_versions_install_id_fkey FOREIGN KEY (install_id) REFERENCES public.installs(id);

